#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

typedef struct {
    int id;
    int type;
    int price;
} Item;

int cmp_type_price(const void *a, const void *b) {
    const Item *ia = (const Item *)a;
    const Item *ib = (const Item *)b;
    if (ia->type != ib->type) {
        return ia->type - ib->type;
    }
    return ia->price - ib->price;
}

// Min-heap baseada em (price, type, id)
typedef struct {
    Item *data;
    int size;
    int capacity;
} MinHeap;

bool heap_less(const Item *a, const Item *b) {
    if (a->price != b->price) {
        return a->price < b->price;
    }
    if (a->type != b->type) {
        return a->type < b->type;
    }
    return a->id < b->id;
}

void heapify_down(MinHeap *h, int idx) {
    int smallest = idx;
    while (true) {
        int left = 2 * idx + 1;
        int right = 2 * idx + 2;

        if (left < h->size && heap_less(&h->data[left], &h->data[smallest])) {
            smallest = left;
        }
        if (right < h->size && heap_less(&h->data[right], &h->data[smallest])) {
            smallest = right;
        }

        if (smallest != idx) {
            Item tmp = h->data[idx];
            h->data[idx] = h->data[smallest];
            h->data[smallest] = tmp;
            idx = smallest;
        } else {
            break;
        }
    }
}

Item heap_pop(MinHeap *h) {
    Item top = h->data[0];
    h->data[0] = h->data[h->size - 1];
    h->size--;
    if (h->size > 0) {
        heapify_down(h, 0);
    }
    return top;
}

int main() {
    // Otimização de I/O
    int N, T;
    if (scanf("%d %d", &N, &T) != 2) return 0;

    Item *items_by_type = (Item *)malloc(N * sizeof(Item));
    Item *heap_array = (Item *)malloc(N * sizeof(Item));
    bool *sold = (bool *)calloc(N, sizeof(bool));

    for (int i = 0; i < N; i++) {
        scanf("%d", &items_by_type[i].type);
        items_by_type[i].id = i;
    }
    for (int i = 0; i < N; i++) {
        scanf("%d", &items_by_type[i].price);
        heap_array[i] = items_by_type[i];
    }

    // Inicializa a Heap em O(N)
    MinHeap heap;
    heap.data = heap_array;
    heap.size = N;
    heap.capacity = N;
    for (int i = (N - 2) / 2; i >= 0; i--) {
        heapify_down(&heap, i);
    }

    // Ordena items_by_type por (type, price)
    qsort(items_by_type, N, sizeof(Item), cmp_type_price);

    // Mapeia o início e o fim de cada tipo no array ordenado
    int *head = (int *)malloc((T + 2) * sizeof(int));
    int *tail = (int *)malloc((T + 2) * sizeof(int));
    for (int i = 1; i <= T + 1; i++) {
        head[i] = -1;
        tail[i] = -1;
    }

    for (int i = 0; i < N; i++) {
        int t = items_by_type[i].type;
        if (head[t] == -1) {
            head[t] = i;
        }
        tail[t] = i;
    }

    int C;
    if (scanf("%d", &C) != 1) return 0;

    long long total_revenue = 0;

    for (int j = 0; j < C; j++) {
        int u;
        scanf("%d", &u);

        if (u == 0) {
            // Cliente indeciso
            while (heap.size > 0 && sold[heap.data[0].id]) {
                heap_pop(&heap);
            }
            if (heap.size > 0) {
                Item chosen = heap_pop(&heap);
                sold[chosen.id] = true;
                total_revenue += chosen.price;
            }
        } else {
            // Cliente decidido
            if (u <= T && head[u] != -1) {
                while (head[u] <= tail[u] && sold[items_by_type[head[u]].id]) {
                    head[u]++;
                }
                if (head[u] <= tail[u]) {
                    Item chosen = items_by_type[head[u]];
                    sold[chosen.id] = true;
                    total_revenue += chosen.price;
                    head[u]++;
                }
            }
        }
    }

    printf("%lld\n", total_revenue);

    free(items_by_type);
    free(heap_array);
    free(sold);
    free(head);
    free(tail);

    return 0;
}
